    "transcript": "パソコン販売店の女の人と男の人が、取引先に提出する見積もりについて話しています。パソコン1台当たりの見積もり価格はいくらにしますか。\n東京商事さんの見積もりは、確かパソコン20台だったわよね。\nそうです。\n1台当たりの価格は？\nなかなか厳しいお客さんで、17万円にしようかと思いますが。\n17万。そうか、先月の大和食品さんへの見積もりはいくらで出したんだっけ？\n18万円でした。\nそれよりは安くなってるけど、あの時は加藤電機さんの17万円に取られちゃったのよね。今回は負けないようにしたいわね。\nええ、そうですね。じゃあ、思い切ってもう少し下げたほうがいいでしょうか。\nそうね。\nじゃあ、どれくらい下げましょうか。\nそうね、1万円かな。うーん、それがぎりぎりの線だわね。\nはい。じゃあ、それで提出します。\nパソコン1台当たりの見積もり価格はいくらにしますか。\n1 20万円。\n2 18万円。\n3 17万円。\n4 16万円。",
    "transcriptWithFurigana": "パソコン販売(はんばい)店(てん)の女(おんな)の人(ひと)と男(おとこ)の人(ひと)が、取引(とりひき)先(さき)に提出(ていしゅつ)する見積(みつ)もりについて話(はな)しています。パソコン1台(だい)当(あ)たりの見積(みつ)もり価格(かかく)はいくらにしますか。\n東京(とうきょう)商事(しょうじ)さんの見積(みつ)もりは、確(たし)かパソコン20台(だい)だったわよね。\nそうです。\n1台(だい)当(あ)たりの価格(かかく)は？\nなかなか厳(きび)しいお客(きゃく)さんで、17万(まん)円(えん)にしようかと思(おも)いますが。\n17万(まん)。そうか、先月(せんげつ)の大和食品(やまとしょくひん)さんへの見積(みつ)もりはいくらで出(だ)したんだっけ？\n18万(まん)円(えん)でした。\nそれよりは安(やす)くなってるけど、あの時(とき)は加藤(かとう)電機(でんき)さんの17万(まん)円(えん)に取(と)られちゃったのよね。今回(こんかい)は負(ま)けないようにしたいわね。\nええ、そうですね。じゃあ、思(おも)い切(き)ってもう少(すこ)し下(さ)げたほうがいいでしょうか。\nそうね。\nじゃあ、どれくらい下(さ)げましょうか。\nそうね、1万(まん)円(えん)かな。うーん、それがぎりぎりの線(せん)だわね。\nはい。じゃあ、それで提出(ていしゅつ)します。\nパソコン1台(だい)当(あ)たりの見積(みつ)もり価格(かかく)はいくらにしますか。\n120万(まん)円(えん)。\n218万(まん)円(えん)。\n317万(まん)円(えん)。\n416万(まん)円(えん)。",
    "translationZhTW": "電腦銷售店的一名女士和一名男士正在談論要提交給客戶的報價。每台電腦的報價要訂為多少？\n東京商事的報價案，記得是二十台電腦吧？\n是的。\n每台的價格呢？\n這位客戶對價格要求很嚴，我想訂為十七萬日圓。\n十七萬啊。上個月給大和食品的報價是多少來著？\n十八萬日圓。\n雖然比那次便宜，但當時被加藤電機十七萬的報價搶走了訂單。這次可不想輸。\n是啊。那是否應該乾脆再降一些？\n嗯。\n那要降多少呢？\n嗯，一萬日圓吧，那就是極限了。\n好的，那我就按這個價格提交。\n每台電腦的報價要訂為多少？\n1 二十萬日圓。\n2 十八萬日圓。\n3 十七萬日圓。\n4 十六萬日圓。",
