    "id": "BJT_TRUE03_P1_S3_Q09",
    "transcript": "二人の技術者がDVDレコーダーの新商品開発について打ち合わせをしています。新商品開発に当たって重要視するのは、価格のほかに何だと言っていますか。\n今のように消費が冷え込んでいると、開発のポイントはデザインより低価格と多機能、つまり安くていろいろなことができるっていうのが重要だと思いますよ。\nうーん、低価格はわかりますが、DVDレコーダーって故障が多いですよね。この前の消費者センターの調査でも、消費者は故障が少ないものを求めているってことが出てましたよ。ですから機能より耐久性をもっと重視するべきですよ。\nただ、耐久性を重視するとどうしても値段が高くなって、売れ行きが心配ですよね。最近の消費者は値段に敏感ですからね。\nおっしゃることはわかるんですが、耐久性は当社の技術に対する信頼性を高めますし、省資源にもなりますから、重要なセールスポイントですよ。\nなるほど、それもそうですね。それでは機能は必要最小限に絞り、故障が少なく長持ちすることを考えることにしましょう。\nええ、そのほうが消費者のニーズに合うと思いますよ。\n新商品開発に当たって重要視するのは、価格のほかに何だと言っていますか。\n1 デザイン性。\n2 機能性。\n3 耐久性。\n4 信頼性。",
    "transcriptWithFurigana": "二人(ふたり)の技術(ぎじゅつ)者(しゃ)がDVDレコーダーの新(しん)商品(しょうひん)開発(かいはつ)について打(う)ち合(あ)わせをしています。新(しん)商品(しょうひん)開発(かいはつ)に当(あ)たって重要(じゅうよう)視(し)するのは、価格(かかく)のほかに何(なん)だと言(い)っていますか。\n今(いま)のように消費(しょうひ)が冷(ひ)え込(こ)んでいると、開発(かいはつ)のポイントはデザインより低(てい)価格(かかく)と多(た)機能(きのう)、つまり安(やす)くていろいろなことができるっていうのが重要(じゅうよう)だと思(おも)いますよ。\nうーん、低(てい)価格(かかく)はわかりますが、DVDレコーダーって故障(こしょう)が多(おお)いですよね。この前(まえ)の消費(しょうひ)者(しゃ)センターの調査(ちょうさ)でも、消費(しょうひ)者(しゃ)は故障(こしょう)が少(すく)ないものを求(もと)めているってことが出(で)てましたよ。ですから機能(きのう)より耐久(たいきゅう)性(せい)をもっと重視(じゅうし)するべきですよ。\nただ、耐久(たいきゅう)性(せい)を重視(じゅうし)するとどうしても値段(ねだん)が高(たか)くなって、売(う)れ行(ゆ)きが心配(しんぱい)ですよね。最近(さいきん)の消費(しょうひ)者(しゃ)は値段(ねだん)に敏感(びんかん)ですからね。\nおっしゃることはわかるんですが、耐久(たいきゅう)性(せい)は当社(とうしゃ)の技術(ぎじゅつ)に対(たい)する信頼(しんらい)性(せい)を高(たか)めますし、省(しょう)資源(しげん)にもなりますから、重要(じゅうよう)なセールスポイントですよ。\nなるほど、それもそうですね。それでは機能(きのう)は必要(ひつよう)最小(さいしょう)限(げん)に絞(しぼ)り、故障(こしょう)が少(すく)なく長持(ながも)ちすることを考(かんが)えることにしましょう。\nええ、そのほうが消費(しょうひ)者(しゃ)のニーズに合(あ)うと思(おも)いますよ。\n新(しん)商品(しょうひん)開発(かいはつ)に当(あ)たって重要(じゅうよう)視(し)するのは、価格(かかく)のほかに何(なん)だと言(い)っていますか。\n1デザイン性(せい)。\n2機能(きのう)性(せい)。\n3耐久(たいきゅう)性(せい)。\n4信頼(しんらい)性(せい)。",
    "translationZhTW": "兩位工程師正在討論DVD錄影機的新產品開發。他們說開發時除了價格之外，還要重視什麼？\n消費像現在這麼低迷，開發的重點應該是低價、多功能，而不是設計。也就是便宜又能做很多事，我認為這很重要。\n嗯，低價可以理解，但DVD錄影機不是經常故障嗎？之前消費者中心的調查也顯示，消費者想要不容易故障的產品。因此，比起功能，更應該重視耐用性。\n不過，重視耐用性難免使價格提高，銷售狀況令人擔心。畢竟最近消費者對價格很敏感。\n我理解您的意思，但耐用性可以提升消費者對本公司技術的信賴，也能節省資源，是重要的賣點。\n原來如此，確實如此。那就把功能限縮到必要的最低限度，著重於不易故障、經久耐用吧。\n是的，我認為這樣更符合消費者的需求。\n他們說開發新產品時，除了價格還要重視什麼？\n1 設計。\n2 功能性。\n3 耐用性。\n4 可靠性。",
