    "id": "BJT_TRUE03_P1_S3_Q13",
    "transcript": "女の人が男の人に自動車部品のサンプルを見せながら話しています。男の人は何に一番興味を持ちましたか。\n本日はお時間を頂戴いたしまして、ありがとうございました。\nいえ、こちらこそご足労いただいて、どうも。\n早速ですが、これが先日お電話でお話しいたしました弊社新製品のサンプルでございます。\n申し上げるまでもありませんが、ハイブリッド車の登場もありまして、業界では部品の小型化が進んでおります。\n弊社のこの製品は既存製品とほとんど同じ価格設定で、容積を今までの3分の2にまで抑えることに成功いたしました。\nまた、今まで以上に環境に配慮してリサイクルがしやすいような材料を使用していますし、それに分解が短時間で行える工夫もしております。\nもちろん耐久性及び性能につきましても、既存製品に劣るものではございません。\n3分の2。確かに小さくなりましたね。うーん、これはいいですね。\nじゃあ、近いうちに両方のエンジニアを交えて、もう少し技術的な話をしましょう。こちらの都合のいい日を改めて連絡します。\nはい、ありがとうございます。\n男の人は何に一番興味を持ちましたか。\n1 大きさ。\n2 価格。\n3 再利用。\n4 性能。",
    "transcriptWithFurigana": "女(おんな)の人(ひと)が男(おとこ)の人(ひと)に自動(じどう)車(しゃ)部品(ぶひん)のサンプルを見(み)せながら話(はな)しています。男(おとこ)の人(ひと)は何(なに)に一番(いちばん)興味(きょうみ)を持(も)ちましたか。\n本日(ほんじつ)はお時間(じかん)を頂戴(ちょうだい)いたしまして、ありがとうございました。\nいえ、こちらこそご足労(そくろう)いただいて、どうも。\n早速(さっそく)ですが、これが先日(せんじつ)お電話(でんわ)でお話(はな)しいたしました弊社(へいしゃ)新(しん)製品(せいひん)のサンプルでございます。\n申(もう)し上(あ)げるまでもありませんが、ハイブリッド車(しゃ)の登場(とうじょう)もありまして、業界(ぎょうかい)では部品(ぶひん)の小型(こがた)化(か)が進(すす)んでおります。\n弊社(へいしゃ)のこの製品(せいひん)は既存(きそん)製(せい)品(ひん)とほとんど同(おな)じ価格(かかく)設定(せってい)で、容積(ようせき)を今(いま)までの3分(ぶん)の2にまで抑(おさ)えることに成功(せいこう)いたしました。\nまた、今(いま)まで以上(いじょう)に環境(かんきょう)に配慮(はいりょ)してリサイクルがしやすいような材料(ざいりょう)を使用(しよう)していますし、それに分解(ぶんかい)が短(たん)時間(じかん)で行(おこな)える工夫(くふう)もしております。\nもちろん耐久(たいきゅう)性(せい)及(およ)び性能(せいのう)につきましても、既存(きそん)製(せい)品(ひん)に劣(おと)るものではございません。\n3分(ぶん)の2。確(たし)かに小(ちい)さくなりましたね。うーん、これはいいですね。\nじゃあ、近(ちか)いうちに両方(りょうほう)のエンジニアを交(まじ)えて、もう少(すこ)し技術(ぎじゅつ)的(てき)な話(はなし)をしましょう。こちらの都合(つごう)のいい日(ひ)を改(あらた)めて連絡(れんらく)します。\nはい、ありがとうございます。\n男(おとこ)の人(ひと)は何(なに)に一番(いちばん)興味(きょうみ)を持(も)ちましたか。\n1大(おお)きさ。\n2価格(かかく)。\n3再(さい)利用(りよう)。\n4性能(せいのう)。",
    "translationZhTW": "一名女士一邊向男士展示汽車零件樣品，一邊說明。男士對哪一點最感興趣？\n感謝您今天撥冗接見。\n哪裡，才要謝謝您特地前來。\n那我就直接進入正題。這是日前電話中向您提到的敝公司新產品樣品。\n想必無須多作說明，隨著油電混合車的問世，業界正在推動零件小型化。\n敝公司這項產品在定價幾乎與原有產品相同的情況下，成功將體積縮小到以往的三分之二。\n此外，我們更重視環保，使用容易回收再利用的材料，也設法讓產品可以在短時間內拆解。\n當然，耐用性與性能也不遜於原有產品。\n三分之二啊，確實變小了。嗯，這個很好。\n那近期邀集雙方工程師，再深入談談技術層面的事。我會另外聯絡，告知我們方便的日期。\n好的，謝謝您。\n男士對哪一點最感興趣？\n1 大小。\n2 價格。\n3 再利用。\n4 性能。",
