    "transcript": "二人の部長が中国プロジェクトについて話しています。スミスさんはいつ中国プロジェクトのメンバーになりますか。\n今度、中国プロジェクトを担当されることになったそうですね。ご苦労さまです。我が社の最重要プロジェクトですから、お役に立てることがあったら何なりと。\nありがとうございます。実は早速で申し訳ありませんが、一つお願いが。\n何でしょうか。\nお宅のスミスさんをですね、今回の中国プロジェクトに出していただきたいんですが、どうでしょうか。\nえ、スミス？\nええ、技術と原価管理がわかる人材がどうしても必要でしてね。それで人事部とも相談したんですが、スミスさんが最適任ということになりました。ぜひともご協力をお願いします。\nうーん、スミスですか。それは困ったな。実はね、彼は今月末にトップに報告するベトナム工場のフィージビリティースタディーのまとめ役をしていましてね。ですから、すぐには難しいですね。\nそうですか。うーん、それではトップ報告が終わってからでしたらどうでしょうか。出していただけますか。\nそうですね。それでは報告が終わって、その後の方向づけなどのめどがついた時点でということで。そうですね、半月くらいかかりますかね。\n結構です。ぜひその線でよろしくお願いいたします。\nスミスさんはいつ中国プロジェクトのメンバーになりますか。\n1 すぐメンバーになる。\n2 今月末にメンバーになる。\n3 トップに報告が終わったらすぐメンバーになる。\n4 トップに報告が終わって半月後にメンバーになる。",
    "transcriptWithFurigana": "二人(ふたり)の部長(ぶちょう)が中国(ちゅうごく)プロジェクトについて話(はな)しています。スミスさんはいつ中国(ちゅうごく)プロジェクトのメンバーになりますか。\n今度(こんど)、中国(ちゅうごく)プロジェクトを担当(たんとう)されることになったそうですね。ご苦労(くろう)さまです。我(わ)が社(しゃ)の最(さい)重要(じゅうよう)プロジェクトですから、お役(やく)に立(た)てることがあったら何(なん)なりと。\nありがとうございます。実(じつ)は早速(さっそく)で申(もう)し訳(わけ)ありませんが、一(ひと)つお願(ねが)いが。\n何(なん)でしょうか。\nお宅(たく)のスミスさんをですね、今回(こんかい)の中国(ちゅうごく)プロジェクトに出(だ)していただきたいんですが、どうでしょうか。\nえ、スミス？\nええ、技術(ぎじゅつ)と原価(げんか)管理(かんり)がわかる人材(じんざい)がどうしても必要(ひつよう)でしてね。それで人事(じんじ)部(ぶ)とも相談(そうだん)したんですが、スミスさんが最(さい)適任(てきにん)ということになりました。ぜひともご協力(きょうりょく)をお願(ねが)いします。\nうーん、スミスですか。それは困(こま)ったな。実(じつ)はね、彼(かれ)は今月(こんげつ)末(まつ)にトップに報告(ほうこく)するベトナム工場(こうじょう)のフィージビリティースタディーのまとめ役(やく)をしていましてね。ですから、すぐには難(むずか)しいですね。\nそうですか。うーん、それではトップ報告(ほうこく)が終(お)わってからでしたらどうでしょうか。出(だ)していただけますか。\nそうですね。それでは報告(ほうこく)が終(お)わって、その後(あと)の方向(ほうこう)づけなどのめどがついた時点(じてん)でということで。そうですね、半月(はんつき)くらいかかりますかね。\n結構(けっこう)です。ぜひその線(せん)でよろしくお願(ねが)いいたします。\nスミスさんはいつ中国(ちゅうごく)プロジェクトのメンバーになりますか。\n1すぐメンバーになる。\n2今月(こんげつ)末(まつ)にメンバーになる。\n3トップに報告(ほうこく)が終(お)わったらすぐメンバーになる。\n4トップに報告(ほうこく)が終(お)わって半月(はんつき)後(あと)にメンバーになる。",
    "translationZhTW": "兩位部長正在談論中國專案。史密斯何時會加入中國專案？\n聽說這次由您負責中國專案，辛苦了。這是本公司最重要的專案，有任何能幫忙的地方，請儘管開口。\n謝謝您。不好意思，這麼快就有一件事想拜託您。\n什麼事呢？\n想請您把部門裡的史密斯調來這次中國專案，不知如何？\n史密斯？\n是的，我們非常需要懂技術與成本管理的人才。與人事部商量後，認為史密斯最適合，還請務必協助。\n嗯，史密斯啊，那可有點難辦。他目前負責彙整越南工廠的可行性研究，要在這個月底向高層報告，所以很難立刻調過去。\n這樣啊，那等向高層報告結束後如何？能讓他調過來嗎？\n嗯，那就等報告結束，而且後續方向等事情大致確定時再調過去。大概還需要半個月吧。\n沒問題，那就請務必照這個方向安排。\n史密斯何時會加入中國專案？\n1 馬上加入。\n2 本月底加入。\n3 向高層報告完就立刻加入。\n4 向高層報告結束半個月後加入。",
