    "id": "BJT_TRUE03_P1_S3_Q15",
    "transcript": "開発担当役員と開発部員が新商品の開発について話しています。担当役員の心配は何ですか。\nようやく新商品完成のめどがつきました。\nそうか。いやあ、ご苦労さん。ところでいつごろ発表できそう？\n最終の確認テストが今月末に終わりますので、遅くとも来月中旬には。\nそうか。ありがとう。来月の役員会に間に合わせたいから、できるだけ急いで頼むよ。コスト、品質は目標どおりだよな。\nはい。これまでの商品に比べてコストは約2分の1、性能は50パーセントアップでいけそうです。これでライバルに負けることはないと思います。\nそれで安心したよ。ところで特許、商標はきちっと押さえてあるだろうな。何といっても最後は知的財産が勝負の決め手になるからね。海外の出願はもう済んだ？\nはい。アメリカ、EU、中国など主なマーケットには出願済みです。\nそうか。とにかく落ちのないように、最後の詰めをよろしく頼むよ。\nかしこまりました。\n担当役員の心配は何ですか。\n1 完成のタイミング。\n2 コスト。\n3 品質。\n4 知的財産権。\nこれで第1部を終わります。次は第2部です。練習。\nフジ電機では残業時間短縮運動を行っています。この表は今月の部門別残業時間の平均対比を表しています。全社平均の1.5倍はどの部門ですか。\n正しい答えは3です。答えは解答用紙の例のように書いてください。これで練習を終わります。それではセクション1のテストを始めます。",
    "transcriptWithFurigana": "開発(かいはつ)担当(たんとう)役員(やくいん)と開発(かいはつ)部(ぶ)員(いん)が新(しん)商品(しょうひん)の開発(かいはつ)について話(はな)しています。担当(たんとう)役員(やくいん)の心配(しんぱい)は何(なん)ですか。\nようやく新(しん)商品(しょうひん)完成(かんせい)のめどがつきました。\nそうか。いやあ、ご苦労(くろう)さん。ところでいつごろ発表(はっぴょう)できそう？\n最終(さいしゅう)の確認(かくにん)テストが今月(こんげつ)末(まつ)に終(お)わりますので、遅(おそ)くとも来月(らいげつ)中旬(ちゅうじゅん)には。\nそうか。ありがとう。来月(らいげつ)の役員(やくいん)会(かい)に間(ま)に合(あ)わせたいから、できるだけ急(いそ)いで頼(たの)むよ。コスト、品質(ひんしつ)は目標(もくひょう)どおりだよな。\nはい。これまでの商品(しょうひん)に比(くら)べてコストは約(やく)2分(ぶん)の1、性能(せいのう)は50パーセントアップでいけそうです。これでライバルに負(ま)けることはないと思(おも)います。\nそれで安心(あんしん)したよ。ところで特許(とっきょ)、商標(しょうひょう)はきちっと押(お)さえてあるだろうな。何(なん)といっても最後(さいご)は知的(ちてき)財産(ざいさん)が勝負(しょうぶ)の決(き)め手(て)になるからね。海外(かいがい)の出願(しゅつがん)はもう済(す)んだ？\nはい。アメリカ、EU、中国(ちゅうごく)など主(おも)なマーケットには出願(しゅつがん)済(ず)みです。\nそうか。とにかく落(お)ちのないように、最後(さいご)の詰(つ)めをよろしく頼(たの)むよ。\nかしこまりました。\n担当(たんとう)役員(やくいん)の心配(しんぱい)は何(なん)ですか。\n1完成(かんせい)のタイミング。\n2コスト。\n3品質(ひんしつ)。\n4知的(ちてき)財産(ざいさん)権(けん)。\nこれで第(だい)1部(ぶ)を終(お)わります。次(つぎ)は第(だい)2部(ぶ)です。練習(れんしゅう)。\nフジ電機(でんき)では残業(ざんぎょう)時間(じかん)短縮(たんしゅく)運動(うんどう)を行(おこな)っています。この表(ひょう)は今月(こんげつ)の部門(ぶもん)別(べつ)残業(ざんぎょう)時間(じかん)の平均(へいきん)対比(たいひ)を表(あらわ)しています。全社(ぜんしゃ)平均(へいきん)の1.5倍(ばい)はどの部門(ぶもん)ですか。\n正(ただ)しい答(こた)えは3です。答(こた)えは解答(かいとう)用(よう)紙(し)の例(れい)のように書(か)いてください。これで練習(れんしゅう)を終(お)わります。それではセクション1のテストを始(はじ)めます。",
    "translationZhTW": "負責研發的主管與研發部員工正在談論新產品開發。主管擔心什麼？\n新產品終於有望完成了。\n是嗎？辛苦了。對了，大概什麼時候能發表？\n最後的確認測試會在本月底結束，所以最晚下個月中旬就可以。\n是嗎，謝謝。我希望趕上下個月的主管會議，麻煩盡快。成本與品質都符合目標吧？\n是的，與以往商品相比，成本約為一半，性能可望提升百分之五十。我認為這樣就不會輸給競爭對手。\n那我就放心了。不過，專利與商標都有確實處理好吧？畢竟最後決定勝負的關鍵還是智慧財產。國外申請辦完了嗎？\n是的，美國、歐盟、中國等主要市場都已經提出申請。\n好。總之，最後收尾請務必確認周全，不要有遺漏。\n明白了。\n主管擔心什麼？\n1 完成的時機。\n2 成本。\n3 品質。\n4 智慧財產權。\n第一部到此結束。接下來是第二部。練習。\n富士電機正在推動縮短加班時間的活動。這張表呈現本月各部門加班時間與平均值的比較。哪個部門是全公司平均值的1.5倍？〔公司名稱漢字待題本確認〕\n正確答案是3。請按照答案紙上的範例填寫答案。練習到此結束，接下來開始第一小節的測驗。",
