    "transcript": "業績のよい販売代理店の店主を対象に招待旅行を計画しています。次のような案がありますが、参加者の中には高齢者もいます。なるべく楽なプランにするには、どの案がいいでしょうか。\nこれでセクション1を終わります。次はセクション2です。練習。\n男の人と女の人がサンプルの発送について話しています。送料はいくらですか。\n横田君、今、手すいてる？\nはい、大丈夫です。何でしょうか。\nあのさ、九州支店から新商品のサンプルを大至急送ってほしいって言ってきているんだ。\nそうですか。えーと、今でしたら5時の宅配便に間に合いますね。\n5時の便か。明日中に着くかな。\nええ、大丈夫だと思います。九州支店でしたね。\nああ。\nで、重さはどのくらいですか。\n7キロ弱。\nわかりました。すぐ手配します。\n送料はいくらですか。\n正しい答えは2です。これで練習を終わります。それではセクション2のテストを始めます。",
    "transcriptWithFurigana": "業績(ぎょうせき)のよい販売(はんばい)代理(だいり)店(てん)の店主(てんしゅ)を対象(たいしょう)に招待(しょうたい)旅行(りょこう)を計画(けいかく)しています。次(つぎ)のような案(あん)がありますが、参加(さんか)者(しゃ)の中(なか)には高齢(こうれい)者(しゃ)もいます。なるべく楽(らく)なプランにするには、どの案(あん)がいいでしょうか。\nこれでセクション1を終(お)わります。次(つぎ)はセクション2です。練習(れんしゅう)。\n男(おとこ)の人(ひと)と女(おんな)の人(ひと)がサンプルの発送(はっそう)について話(はな)しています。送料(そうりょう)はいくらですか。\n横田(よこた)君(くん)、今(いま)、手(て)すいてる？\nはい、大丈夫(だいじょうぶ)です。何(なん)でしょうか。\nあのさ、九州(きゅうしゅう)支店(してん)から新(しん)商品(しょうひん)のサンプルを大至急(だいしきゅう)送(おく)ってほしいって言(い)ってきているんだ。\nそうですか。えーと、今(いま)でしたら5時(じ)の宅配(たくはい)便(びん)に間(ま)に合(あ)いますね。\n5時(じ)の便(びん)か。明日(あす)中(ちゅう)に着(つ)くかな。\nええ、大丈夫(だいじょうぶ)だと思(おも)います。九州(きゅうしゅう)支店(してん)でしたね。\nああ。\nで、重(おも)さはどのくらいですか。\n7キロ弱(じゃく)。\nわかりました。すぐ手配(てはい)します。\n送料(そうりょう)はいくらですか。\n正(ただ)しい答(こた)えは2です。これで練習(れんしゅう)を終(お)わります。それではセクション2のテストを始(はじ)めます。",
    "translationZhTW": "正在規劃一趟招待業績優良之銷售代理店店主的旅行。有以下幾個方案，但參加者中也有高齡者。若要盡量安排輕鬆的行程，哪個方案比較好？\n第一小節到此結束。接下來是第二小節。練習。\n一名男士與一名女士正在談論寄送樣品。運費是多少？\n橫田，你現在有空嗎？\n有，沒問題。什麼事呢？\n九州分店聯絡說，希望我們盡速寄送新商品的樣品。\n這樣啊，現在的話還趕得上五點的宅配。\n五點的那班啊，明天內能到嗎？\n我想沒問題。是九州分店，對吧？\n嗯。\n那重量大約多少？\n不到七公斤。\n明白了，我立刻安排。\n運費是多少？\n正確答案是2。練習到此結束，接下來開始第二小節的測驗。",
