    "transcript": "文房具メーカーが販売協力会社の幹部を集めて、生産計画説明会を開催しています。今、質疑応答に入り、男の人が質問を始めました。この質問に答える人は誰ですか。\n新商品の多機能ボールペンは、3年前に他社に先駆けて販売を開始して以来、着実に市場が広がっていますね。\nこの商品に限らず、御社は高い技術開発力をもって次々とヒット商品を生み出していらっしゃいます。我々協力会社としてもうれしい限りです。\nところで、先ほど日本国内の伸び率について、予測とその予測の背景を詳しくご説明いただきましたが、海外市場についてはいかがでしょうか。\n特に中国をはじめとするアジア市場は皆の注目するところですので、このあたりをご説明いただければと思いますが。\nこの質問に答える人は誰ですか。",
