    "id": "BJT_TRUE03_P2_S2_Q03",
    "transcript": "部長と秘書が電話で話しています。秘書はどのレストランを予約しますか。\n平野さん、ニューヨークから見えたアナリストのバーニーさんをディナーに招待したいんで、あさっての晩7時にお店を予約してほしいんだけど。\nはい。何人のご予定ですか。\nお客様もご一緒で5人分。\nはい、かしこまりました。バーニーさんはどんなものがお好きなんでしょうか。\n和食がお好みなんだ。和食はヘルシーだし、見た目がきれいだってお気に入りなんだよ。\nそうですか。\n刺身にも目がないし、日本に来られた時はいつも和食の店にご案内することにしてるんだよ。\nご一緒のお客様は生ものは大丈夫なんでしょうか。\nたぶんね。皆さん日本通の方ばかりだって聞いてる。\nそうですか。えっと、今、外国の方に人気のあるレストランのリストを見ているんですが。そうですね、じゃあわかりました。よさそうなお店がありますので、5人で予約しておきます。\nじゃあ、頼みます。\n秘書はどのレストランを予約しますか。",
