    "transcript": "消費者の商品イメージを知るためにアンケート調査を行います。二人の担当者が、ほかの部員の作成した質問項目案を見ながら話しています。どの案にしますか。\n何しろこの商品は日用品なんだから、親しみやすさというのは欠かせないんじゃないの。\nそうね、確かに。それから、あか抜けているかどうかという点も侮れないわよ。つまり、デザイン性も大きいポイントよね。\nそうだよな。やっぱりまずは見た目だからね。\nそれにもちろん匂いも。最近はハーブがすごい人気じゃない。こだわる人、多いと思うな。\nうん、そうだね。じゃあ、豪華さってのはどう？\nうーん、この商品のターゲットを考えたら、それほど重要じゃない気がするな。\nそうだよね。じゃあ、それは外そう。大きさもどう捉えているか知りたいところだな。\nそうね。扱いやすさにも通じるもんね。\nじゃあ、この4項目で、あとはこれを具体的にしていきましょう。\nそうだね。\nどの案にしますか。",
    "transcriptWithFurigana": "消費(しょうひ)者(しゃ)の商品(しょうひん)イメージを知(し)るためにアンケート調査(ちょうさ)を行(おこな)います。二人(ふたり)の担当(たんとう)者(しゃ)が、ほかの部員(ぶいん)の作成(さくせい)した質問(しつもん)項目(こうもく)案(あん)を見(み)ながら話(はな)しています。どの案(あん)にしますか。\n何(なに)しろこの商品(しょうひん)は日用(にちよう)品(ひん)なんだから、親(した)しみやすさというのは欠(か)かせないんじゃないの。\nそうね、確(たし)かに。それから、あか抜(ぬ)けているかどうかという点(てん)も侮(あなど)れないわよ。つまり、デザイン性(せい)も大(おお)きいポイントよね。\nそうだよな。やっぱりまずは見(み)た目(め)だからね。\nそれにもちろん匂(にお)いも。最近(さいきん)はハーブがすごい人気(にんき)じゃない。こだわる人(ひと)、多(おお)いと思(おも)うな。\nうん、そうだね。じゃあ、豪華(ごうか)さってのはどう？\nうーん、この商品(しょうひん)のターゲットを考(かんが)えたら、それほど重要(じゅうよう)じゃない気(き)がするな。\nそうだよね。じゃあ、それは外(はず)そう。大(おお)きさもどう捉(とら)えているか知(し)りたいところだな。\nそうね。扱(あつか)いやすさにも通(つう)じるもんね。\nじゃあ、この4項目(こうもく)で、あとはこれを具体(ぐたい)的(てき)にしていきましょう。\nそうだね。\nどの案(あん)にしますか。",
    "translationZhTW": "為了解消費者對商品的印象，將進行問卷調查。兩位負責人正一邊看其他部員擬定的問項方案，一邊討論。他們會選哪個方案？\n畢竟這是日用品，親切感應該是不可或缺的吧。\n是啊，確實。另外，看起來是否時尚也不可忽視，也就是設計感也是重要重點。\n沒錯，首先看的果然還是外觀。\n當然還有氣味。最近香草不是很受歡迎嗎？我想很講究這點的人不少。\n嗯，對。那豪華感呢？\n嗯，考慮這項商品的目標客群，我覺得沒那麼重要。\n對，那就去掉。大小方面，也想了解消費者怎麼看。\n是啊，這也關係到是否方便使用。\n那就用這四個項目，接著把內容具體化吧。\n好。\n他們會選哪個方案？",
