    "id": "BJT_TRUE03_P2_S2_Q05",
    "transcript": "部長が経営会議で海外生産についてプレゼンテーションをしています。部長はどの国に工場を建設したいと思っていますか。\n我が社の商品は品質面では高い評価を得ていますが、コスト競争力強化という点から海外生産は避けて通れないものと思います。\n当プロジェクトチームでは候補地をアジア4か国に絞って、事前調査を進めてまいりました。その結果はお手元の資料のとおりでございます。\nただ、海外での工場建設には莫大な投資を必要としますので、政治的な安定は欠かせません。\nしたがって最終判断に当たっては、コスト削減額もさることながら、カントリーリスクを最も重視するべきだと考えております。以上から。\n部長はどの国に工場を建設したいと思っていますか。",
    "transcriptWithFurigana": "部長(ぶちょう)が経営(けいえい)会議(かいぎ)で海外(かいがい)生産(せいさん)についてプレゼンテーションをしています。部長(ぶちょう)はどの国(くに)に工場(こうじょう)を建設(けんせつ)したいと思(おも)っていますか。\n我(わ)が社(しゃ)の商品(しょうひん)は品質(ひんしつ)面(めん)では高(たか)い評価(ひょうか)を得(え)ていますが、コスト競争(きょうそう)力(りょく)強化(きょうか)という点(てん)から海外(かいがい)生産(せいさん)は避(さ)けて通(とお)れないものと思(おも)います。\n当(とう)プロジェクトチームでは候補(こうほ)地(ち)をアジア4か国(こく)に絞(しぼ)って、事前(じぜん)調査(ちょうさ)を進(すす)めてまいりました。その結果(けっか)はお手元(てもと)の資料(しりょう)のとおりでございます。\nただ、海外(かいがい)での工場(こうじょう)建設(けんせつ)には莫大(ばくだい)な投資(とうし)を必要(ひつよう)としますので、政治(せいじ)的(てき)な安定(あんてい)は欠(か)かせません。\nしたがって最終(さいしゅう)判断(はんだん)に当(あ)たっては、コスト削減(さくげん)額(がく)もさることながら、カントリーリスクを最(もっと)も重視(じゅうし)するべきだと考(かんが)えております。以上(いじょう)から。\n部長(ぶちょう)はどの国(くに)に工場(こうじょう)を建設(けんせつ)したいと思(おも)っていますか。",
    "translationZhTW": "部長在經營會議上就海外生產進行簡報。他希望在哪個國家興建工廠？\n本公司商品在品質方面獲得高度評價，但從強化成本競爭力來看，海外生產是無可迴避的方向。\n本專案小組將候選地點限縮到亞洲四個國家，進行前期調查，結果如各位手邊資料所示。\n不過，在海外興建工廠需要龐大投資，因此政治穩定不可或缺。\n因此，在做最後判斷時，雖然成本削減額很重要，但我認為最應重視的是國家風險。根據以上幾點……\n部長希望在哪個國家興建工廠？",
