    "transcript": "財務部の部長と課長が、銀行からの借入金の利率について話しています。銀行からの借入利率は何パーセントですか。\n鈴木課長、子会社の東京商事から短期融資の依頼があったよね。うちの取引銀行に頼んでくれないかって言われてたあの件、どうなった？\nはい、今6か月以内の短期借り入れということで銀行と交渉しています。\n3億5000万円って言ってたな。で、銀行の返事はどうなの？\nええ、当然のことなんですが、借入期間と金額によってかなり金利に差があります。ちょっとすみません、今表を出します。これです。この表のとおりなんです。\nどれ。うーん、ちょっと高いね。もう少し何とかならないのかね。\nはい、実はですね、私ども親会社が保証することを条件として銀行と交渉したんですが、その結果、この表よりすべて0.1パーセント低い線で受けていただけるということになりました。\n0.1パーセントか。それならいいじゃない。よし、じゃあ今回はそれで手を打とう。\nはい。では、そのように手配いたします。\n銀行からの借入利率は何パーセントですか。",
