    "transcript": "社内報の新年号に社長の談話を載せるため、社長にインタビューをしました。題名の候補を四つ考えました。どの題名がいいですか。\n早速ですが、社長の今年の抱負をお聞かせいただけますか。\n現在の5か年計画で掲げている顧客満足度の向上や環境整備への取り組みのテーマは継続してやっていきますが、今年は新たに従業員の意識改革にスポットを当ててみたいと思っています。\n確かに当社は優秀な人材で定評があるんですが、でもその持っている能力が十分発揮できているとは言えません。\nどこが問題なんでしょうか。\nつまり、事なかれ主義なんですね。寄らば大樹の陰ということわざがありますが、そんな安定志向の人が増えているのは残念です。\nでは、何を変えていけばいいと思われますか。\n結局、従業員一人一人の意識の持ち方でしょうね。私としては失敗を恐れないで物事に挑戦していくような、そんな企業風土に変えていきたいと思っています。\nどの題名がいいですか。",
