    "transcript": "会社で男の人と女の人が出張費用について話しています。男の人はどんな出張精算書を書きますか。\nあのさ、この間アメリカ出張したじゃない。その時の出張費の精算なんだけどね。ちょっと細かいことがわかんないんだけど。\nはい、何でしょうか。\n自宅、空港の往復の交通費は入れていいんだよね。\nええ、いいですよ。\nそれから、スーツケースを空港まで運んでもらったんだけど、片道だけ。\nそれは宅配便代として交通費の次に記入しておいてください。\nオーケー。それと、現地でインフルエンザにかかっちゃって病院に行ったんだけど、こういうのってどうなるの？ 治療費もその紙に書いていいの？\nああ、それは別途請求してください。後で用紙をお渡しします。\nわかった。どうもありがとう。\n男の人はどんな出張精算書を書きますか。",
