    "id": "BJT_TRUE03_P2_S2_Q12",
    "transcript": "東京の本社でeラーニングを取り入れる計画があります。近々フェアが開かれるので、担当の二人が見学に行きます。男の人はどの会場に行きますか。\n今度eラーニングのフェアがあるの知ってる？\nえ、本当？\nおとといの新聞に載ってたから持ってきたわよ。ほら、これ見て。\nへえ、会場は4か所か。旅行がてら大阪か名古屋に行くかな。季節もいいし。\nそれいいわね、と言いたいところだけど、まさか。そんなの許可が下りるわけないじゃない。引き締め、引き締めってうるさく言われてるじゃないの。有給取って自腹でっていうなら話は別だけど。\nそうだね。じゃあ近場で。えーと、東京会場は4月9日、横浜会場は4月10日だね。一緒に行く？\nああ、そうね。でも私は帰りが便利なように横浜にするわ。\n横浜は午後か。その日の夕方はちょっと所用が。\nああ、そう。\n男の人はどの会場に行きますか。",
    "transcriptWithFurigana": "東京(とうきょう)の本社(ほんしゃ)でeラーニングを取(と)り入(い)れる計画(けいかく)があります。近々(ちかぢか)フェアが開(ひら)かれるので、担当(たんとう)の二人(ふたり)が見学(けんがく)に行(い)きます。男(おとこ)の人(ひと)はどの会場(かいじょう)に行(い)きますか。\n今度(こんど)eラーニングのフェアがあるの知(し)ってる？\nえ、本当(ほんとう)？\nおとといの新聞(しんぶん)に載(の)ってたから持(も)ってきたわよ。ほら、これ見(み)て。\nへえ、会場(かいじょう)は4か所(しょ)か。旅行(りょこう)がてら大阪(おおさか)か名古屋(なごや)に行(い)くかな。季節(きせつ)もいいし。\nそれいいわね、と言(い)いたいところだけど、まさか。そんなの許可(きょか)が下(お)りるわけないじゃない。引(ひ)き締(し)め、引(ひ)き締(し)めってうるさく言(い)われてるじゃないの。有給(ゆうきゅう)取(と)って自腹(じばら)でっていうなら話(はなし)は別(べつ)だけど。\nそうだね。じゃあ近場(ちかば)で。えーと、東京(とうきょう)会場(かいじょう)は4月9日(しがつここのか)、横浜(よこはま)会場(かいじょう)は4月10日(しがつとおか)だね。一緒(いっしょ)に行(い)く？\nああ、そうね。でも私(わたし)は帰(かえ)りが便利(べんり)なように横浜(よこはま)にするわ。\n横浜(よこはま)は午後(ごご)か。その日(ひ)の夕方(ゆうがた)はちょっと所用(しょよう)が。\nああ、そう。\n男(おとこ)の人(ひと)はどの会場(かいじょう)に行(い)きますか。",
    "translationZhTW": "東京總公司有導入數位學習的計畫。近期將舉行展覽，因此兩位負責人要去參觀。男士會去哪個會場？\n你知道近期有數位學習展覽嗎？\n真的嗎？\n前天報紙上有刊登，我帶來了，你看這個。\n喔，有四個會場啊。不如去大阪或名古屋，順便旅行，季節也正好。\n本來想說好主意，但怎麼可能，公司不會批准吧。不是一直強調要緊縮開支嗎？除非你請年假自己出錢，那就另當別論。\n也是，那就選近一點的。東京會場是四月九日，橫濱會場是四月十日。一起去嗎？\n嗯，不過為了回家方便，我選橫濱。\n橫濱是下午啊，那天傍晚我有點事情。\n這樣啊。\n男士會去哪個會場？",
