    "id": "BJT_TRUE03_P2_S2_Q13",
    "transcript": "経営会議で部長が今年度の営業計画について話しています。一番強化したい計画案はどれですか。\nそれでは今年度の営業計画についてご説明申し上げます。\nまず店頭販売計画ですが、これは好調に進んでおりますので、従来どおり力を入れていきたいと思います。\n次に前年度より始めた法人推進計画ですが、おかげさまで契約件数が着実に増えております。1契約当たりの額が非常に大きく、コストパフォーマンスの観点からも特に主力にしたいと考えております。\n通信販売計画につきましては、順調に数字に結びついているのですが、その反面、飛躍的な数字は期待できないのが現状です。\n最後にネット限定販売計画に関しては、次年度に本格的に稼働する予定にしていますので、今年度は準備段階と考えております。\nそれでは、それぞれの計画について具体的に。\n一番強化したい計画案はどれですか。",
    "transcriptWithFurigana": "経営(けいえい)会議(かいぎ)で部長(ぶちょう)が今(こん)年度(ねんど)の営業(えいぎょう)計画(けいかく)について話(はな)しています。一番(いちばん)強化(きょうか)したい計画(けいかく)案(あん)はどれですか。\nそれでは今(こん)年度(ねんど)の営業(えいぎょう)計画(けいかく)についてご説明(せつめい)申(もう)し上(あ)げます。\nまず店頭(てんとう)販売(はんばい)計画(けいかく)ですが、これは好調(こうちょう)に進(すす)んでおりますので、従来(じゅうらい)どおり力(ちから)を入(い)れていきたいと思(おも)います。\n次(つぎ)に前(ぜん)年度(ねんど)より始(はじ)めた法人(ほうじん)推進(すいしん)計画(けいかく)ですが、おかげさまで契約(けいやく)件数(けんすう)が着実(ちゃくじつ)に増(ふ)えております。1契約(けいやく)当(あ)たりの額(がく)が非常(ひじょう)に大(おお)きく、コストパフォーマンスの観点(かんてん)からも特(とく)に主力(しゅりょく)にしたいと考(かんが)えております。\n通信(つうしん)販売(はんばい)計画(けいかく)につきましては、順調(じゅんちょう)に数字(すうじ)に結(むす)びついているのですが、その反面(はんめん)、飛躍(ひやく)的(てき)な数字(すうじ)は期待(きたい)できないのが現状(げんじょう)です。\n最後(さいご)にネット限定(げんてい)販売(はんばい)計画(けいかく)に関(かん)しては、次(じ)年度(ねんど)に本格(ほんかく)的(てき)に稼働(かどう)する予定(よてい)にしていますので、今(こん)年度(ねんど)は準備(じゅんび)段階(だんかい)と考(かんが)えております。\nそれでは、それぞれの計画(けいかく)について具体(ぐたい)的(てき)に。\n一番(いちばん)強化(きょうか)したい計画(けいかく)案(あん)はどれですか。",
    "translationZhTW": "部長在經營會議上談論本年度的業務計畫。他最想加強的是哪個方案？\n那麼，以下說明本年度的業務計畫。\n首先是店面銷售計畫，由於進展良好，打算維持以往的投入。\n其次是從上一年度開始的法人客戶推廣計畫，托大家的福，簽約件數穩定增加。每筆合約的金額非常大，從成本效益來看，也特別希望將其作為主力。\n郵購計畫方面，雖然順利反映在業績上，但另一方面，目前也難以期待大幅成長。\n最後是網路限定銷售計畫，預計下一年度正式運作，因此本年度定位為準備階段。\n接下來，針對各項計畫具體說明……\n最想加強的是哪個方案？",
